inline bool uart_utf8(const String& text) {
    for (unsigned int i = 0; i < text.length();) {
        unsigned char c = text[i]; unsigned int n = c < 128 ? 1 : c >= 194 && c <= 223 ? 2 : c >= 224 && c <= 239 ? 3 : c >= 240 && c <= 244 ? 4 : 0;
        if (!n || i + n > text.length()) return false;
        for (unsigned int j = 1; j < n; j++) if ((text[i+j] & 192) != 128) return false;
        if (n == 3 && ((c == 224 && (unsigned char)text[i+1] < 160) || (c == 237 && (unsigned char)text[i+1] >= 160))) return false;
        if (n == 4 && ((c == 240 && (unsigned char)text[i+1] < 144) || (c == 244 && (unsigned char)text[i+1] >= 144))) return false;
        i += n;
    } return true;
}
inline bool uart_space(uint32_t c) { return (c >= 9 && c <= 13) || (c >= 28 && c <= 32) || c == 0x85 || c == 0xA0 || c == 0x1680 || (c >= 0x2000 && c <= 0x200A) || c == 0x2028 || c == 0x2029 || c == 0x202F || c == 0x205F || c == 0x3000; }
inline RbUart& uart_puerto(RbUart& d, const char* bloque) {
